<script setup lang="ts">
import { ref } from 'vue'
import { addressApi, administrationApi, ApiError, type WorkshopPayload } from '../services/api'
import { useAuthStore } from '../stores/auth'

const auth = useAuthStore(); const form = ref(); const error = ref(''); const success = ref(''); const addressHint = ref('')
const model = ref<WorkshopPayload>({ name: '', rfc: '', email: '', street_number: '', neighborhood: '', postal_code: '', state: '', municipality: '', photo_url: '' })
const emailRule = (v: string) => /.+@.+\..+/.test(v) || 'Correo inválido'
const cpRule = (v: string) => /^\d{5}$/.test(v) || 'El código postal debe tener 5 dígitos'
const rfcRule = (v: string) => /^[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}$/.test(v) || 'RFC inválido. Ejemplo: XAXX010101000'
function showLookupError(e: unknown) { addressHint.value = e instanceof ApiError ? e.message : 'No fue posible consultar la dirección.' }
async function lookupPostalCode() { model.value.postal_code=model.value.postal_code.replace(/\D/g,'').slice(0,5); addressHint.value=''; if(model.value.postal_code.length!==5) return; try { const data=await addressApi.byPostalCode(model.value.postal_code); model.value.state=data.state; model.value.municipality=data.municipality; model.value.neighborhood=data.neighborhoods[0] ?? ''; addressHint.value=data.neighborhoods.length>1 ? `Se asignó “${data.neighborhoods[0]}”. Otras colonias para este CP: ${data.neighborhoods.slice(1).join(', ')}.` : 'Dirección completada desde la API.' } catch(e) { showLookupError(e) } }
async function lookupAddress() { addressHint.value=''; if(!model.value.state || !model.value.municipality || !model.value.neighborhood) return; try { const data=await addressApi.byAddress(model.value.state,model.value.municipality,model.value.neighborhood); model.value.postal_code=data.postal_code; model.value.state=data.state; model.value.municipality=data.municipality; addressHint.value='Código postal completado desde la API.' } catch(e) { showLookupError(e) } }
async function save() { const validation=await form.value.validate(); if(!validation.valid) return; error.value=''; success.value=''; try { const payload={...model.value,rfc:model.value.rfc.toUpperCase(),photo_url:model.value.photo_url||undefined}; await administrationApi.createWorkshop(payload,auth.token); success.value='Taller registrado correctamente.' } catch(e) { error.value=e instanceof ApiError?e.message:'No fue posible registrar el taller.' } }
</script>
<template><v-app><v-app-bar color="primary"><v-app-bar-title><v-icon>mdi-store-cog</v-icon> Alta de taller mecánico</v-app-bar-title><v-btn to="/panel" prepend-icon="mdi-view-dashboard">Panel</v-btn></v-app-bar><v-main><v-container class="py-8"><v-card max-width="920" class="mx-auto"><v-card-item><v-card-title>Datos del taller</v-card-title><v-card-subtitle>Consulta de dirección mediante API local de Tula de Allende, Hidalgo.</v-card-subtitle></v-card-item><v-card-text><v-alert v-if="error" type="error" class="mb-4">{{error}}</v-alert><v-alert v-if="success" type="success" class="mb-4">{{success}}</v-alert><v-form ref="form" @submit.prevent="save"><v-row><v-col cols="12" md="6"><v-text-field v-model="model.name" label="Nombre completo del taller" :rules="[v=>!!v||'Campo obligatorio']"/></v-col><v-col cols="12" md="6"><v-text-field v-model="model.rfc" label="RFC" :rules="[rfcRule]" @update:model-value="model.rfc=model.rfc.toUpperCase()"/></v-col><v-col cols="12" md="6"><v-text-field v-model="model.email" label="Correo de contacto" :rules="[emailRule]"/></v-col><v-col cols="12" md="6"><v-text-field v-model="model.street_number" label="Calle y número" :rules="[v=>!!v||'Campo obligatorio']"/></v-col><v-col cols="12" md="4"><v-text-field v-model="model.postal_code" label="Código postal" maxlength="5" :rules="[cpRule]" @update:model-value="lookupPostalCode"/></v-col><v-col cols="12" md="4"><v-text-field v-model="model.state" label="Estado" :rules="[v=>!!v||'Campo obligatorio']" @blur="lookupAddress"/></v-col><v-col cols="12" md="4"><v-text-field v-model="model.municipality" label="Municipio" :rules="[v=>!!v||'Campo obligatorio']" @blur="lookupAddress"/></v-col><v-col cols="12" md="6"><v-text-field v-model="model.neighborhood" label="Colonia" :rules="[v=>!!v||'Campo obligatorio']" @blur="lookupAddress"/></v-col><v-col cols="12" md="6"><v-text-field v-model="model.photo_url" label="URL de foto del taller (opcional)" type="url"/></v-col></v-row><v-alert v-if="addressHint" :type="addressHint.startsWith('No') || addressHint.startsWith('El código') ? 'warning' : 'info'" density="compact" class="mb-4">{{addressHint}}</v-alert><v-btn type="submit" color="primary" prepend-icon="mdi-content-save">Guardar taller</v-btn></v-form></v-card-text></v-card></v-container></v-main></v-app></template>
